-- Sprint 5 deterministic remediation guides for Grade 7 Physics Chapter I.
-- Provisional development content; SME validation remains deferred.

with guides(skill_code, misconception_code, title_hy, strategy_hy, hint_1_hy, hint_2_hy, worked_example_hy) as (
values
('PHY7-U01-S01','phenomenon_classification','Ֆիզիկական երևույթների դասակարգում','Նախ որոշիր՝ ինչ փոփոխություն է տեղի ունենում, հետո կապիր այն երևույթի տեսակի հետ։','Հարցրու քեզ՝ մարմնի շարժո՞ւմն է փոխվում, ջերմաստիճա՞նը, լո՞ւյսը, ձա՞յնը, թե՞ մագնիսական ազդեցությունն է։','Մի ընտրիր միայն առարկայի անունով. դասակարգիր հենց տեղի ունեցող փոփոխությունը։','Օրինակ՝ հայելուց լույսի անդրադարձը օպտիկական երևույթ է, որովհետև փոփոխությունը կապված է լույսի տարածման հետ։'),
('PHY7-U01-S02','body_material_phenomenon','Մարմին, նյութ, երևույթ','Տարբերակիր «ինչ առարկա է», «ինչից է պատրաստված» և «ինչ է տեղի ունենում» հարցերը։','Մարմինը առանձին առարկան է, նյութը՝ այն, ինչից մարմինը պատրաստված է։','Երևույթը գործողություն կամ փոփոխություն է, ոչ թե առարկա կամ նյութ։','Օրինակ՝ «ապակե բաժակի կոտրվելը» արտահայտությունում բաժակը մարմին է, ապակին՝ նյութ, կոտրվելը՝ երևույթ։'),
('PHY7-U01-S03','scientist_fact_recall','Ֆիզիկոսներ և գիտական ներդրումներ','Կապիր յուրաքանչյուր գիտնականի անունը մեկ հիմնական ներդրման կամ հաստատության հետ։','Փորձիր նախ հիշել ոչ թե տարեթիվը, այլ գիտնականի հիմնական գաղափարը կամ հայտնագործությունը։','Եթե երկու տարբերակ նման են, վերացրու նրանք, որոնց գիտական ոլորտը չի համապատասխանում հարցին։','Օրինակ՝ Գալիլեյը կապված է փորձարարական մեթոդի զարգացման հետ, Նյուտոնը՝ դասական մեխանիկայի հիմնարար օրենքների հետ։'),
('PHY7-U01-S04','observation_vs_experiment','Դիտում թե՞ փորձ','Որոշիր՝ հետազոտողը պարզապես հետևո՞ւմ է երևույթին, թե՞ փոխում/վերահսկում է պայմանները։','Եթե պայմանները չեն փոխվում և միայն գրանցում ենք տեսածը, դա սովորաբար դիտում է։','Եթե պայմանները վերահսկվում կամ կրկնվում են և կատարվում են չափումներ, դա սովորաբար փորձ է։','Օրինակ՝ ծիածանին հետևելը դիտում է, իսկ նույն նյութը տարբեր ջերմաստիճաններում բազմիցս տաքացնելն ու չափելը՝ փորձ։'),
('PHY7-U01-S05','inquiry_chain','Գիտական հետազոտության քայլերը','Պահպանիր տրամաբանական հերթականությունը՝ հարց/դիտում → վարկած → փորձ/տվյալներ → եզրակացություն։','Վարկածը դեռ ապացուցված փաստ չէ. այն ենթադրություն է, որը պետք է ստուգել։','Փորձը պետք է արտադրի տվյալներ, որոնց հիման վրա կարելի է ընդունել, փոփոխել կամ մերժել վարկածը։','Օրինակ՝ «ավելի տաք ջուրը շուտ է գոլորշիանում» ենթադրությունը վարկած է. այն ստուգելու համար պետք է համեմատելի պայմաններում չափումներ կատարել։'),
('PHY7-U01-S06','quantity_unit_instrument','Մեծություն, միավոր, սարք','Յուրաքանչյուր ֆիզիկական մեծության համար առանձին հիշիր նրա չափման միավորը և համապատասխան չափիչ սարքը։','Հարցրու՝ ինչն ենք չափում. երկարությո՞ւն, ժամանակ, զանգվա՞ծ, ջերմաստիճա՞ն։','Հետո ընտրիր ճիշտ միավորը և այն սարքը, որը հենց այդ մեծությունն է չափում։','Օրինակ՝ երկարությունը չափվում է մետրերով, իսկ գործնականում կարող է չափվել քանոնով կամ ժապավենաչափով։'),
('PHY7-U01-S07','unit_conversion','Չափման միավորների փոխարկում','Գրիր հայտնի կապը երկու միավորների միջև և հետո որոշիր՝ բազմապատկե՞լ, թե՞ բաժանել։','Մեծ միավորից փոքր միավոր անցնելիս թիվը սովորաբար մեծանում է, օրինակ՝ 1 կմ = 1000 մ։','Փոքր միավորից մեծ միավոր անցնելիս թիվը սովորաբար փոքրանում է, օրինակ՝ 100 սմ = 1 մ։','Օրինակ՝ 2.5 կմ = 2.5 × 1000 = 2500 մ։'),
('PHY7-U01-S08','scale_division_value','Սանդղակի բաժանման արժեք','Գտիր երկու թվային նշումների տարբերությունը և բաժանիր նրանց միջև եղած հավասար միջակայքների քանակին։','Մի հաշվիր միայն գծիկները. հաշվի՛ր հավասար միջակայքները երկու հայտնի նշումների միջև։','Օգտագործիր բանաձևը՝ մեկ բաժանման արժեք = (վերին արժեք − ստորին արժեք) ÷ բաժանումների քանակ։','Օրինակ՝ 0-ից 20 սմ սանդղակը բաժանված է 4 հավասար մասի. (20 − 0) ÷ 4 = 5 սմ մեկ բաժանման համար։'),
('PHY7-U01-S09','measurement_error_precision','Չափման սխալ և ճշգրտություն','Կապիր չափման հնարավոր սխալը սարքի ամենափոքր բաժանման հետ և համեմատի՛ր սարքերը ըստ բաժանման արժեքի։','Մեր ընթացիկ կանոնով գործիքային չափման սխալը ընդունվում է մոտավորապես մեկ բաժանման արժեքի կեսը։','Ավելի փոքր բաժանման արժեք ունեցող սարքը սովորաբար թույլ է տալիս ավելի ճշգրիտ չափում։','Օրինակ՝ եթե բաժանման արժեքը 0.4 սմ է, ապա ընդունվող սխալը 0.2 սմ է։ 0.1 սմ բաժանում ունեցող քանոնը սովորաբար ավելի ճշգրիտ է, քան 0.5 սմ բաժանում ունեցողը։'),
('PHY7-U01-S10','measurement_investigation','Չափման փորձի պլանավորում','Փորձը բաժանիր քայլերի՝ ինչ չափել սկզբում, ինչ փոխել, ինչ չափել հետո և ինչ հաշվարկել։','Անկանոն մարմնի ծավալի համար չափիր ջրի սկզբնական ծավալը V₁, հետո մարմնի հետ ծավալը V₂։','Մարմնի ծավալը ստացվում է տարբերությամբ՝ V = V₂ − V₁։ Միավորները պետք է նույնը լինեն։','Օրինակ՝ եթե V₁ = 35 սմ³, իսկ V₂ = 52 սմ³, ապա մարմնի ծավալը 52 − 35 = 17 սմ³ է։')
)
insert into public.skill_remediation_guides(skill_id, misconception_code, title_hy, strategy_hy, hint_1_hy, hint_2_hy, worked_example_hy, status)
select s.id, g.misconception_code, g.title_hy, g.strategy_hy, g.hint_1_hy, g.hint_2_hy, g.worked_example_hy, 'published'
from guides g
join public.skills s on s.code = g.skill_code
on conflict (skill_id, misconception_code) do update set
  title_hy = excluded.title_hy,
  strategy_hy = excluded.strategy_hy,
  hint_1_hy = excluded.hint_1_hy,
  hint_2_hy = excluded.hint_2_hy,
  worked_example_hy = excluded.worked_example_hy,
  status = excluded.status,
  updated_at = now();
